import{_ as n,o as t,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ATLAS Icon Bibliothek","description":"Home-Assistant-Iconsets suchen, durchsuchen und Icon-Namen kopieren.","frontmatter":{"title":"ATLAS Icon Bibliothek","description":"Home-Assistant-Iconsets suchen, durchsuchen und Icon-Namen kopieren."},"headers":[],"relativePath":"projects/atlas-plugins/icon-library.md","filePath":"projects/atlas-plugins/icon-library.md","lastUpdated":1792861636000}'),a={name:"projects/atlas-plugins/icon-library.md"};function r(o,e,l,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="atlas-icon-bibliothek" tabindex="-1">ATLAS Icon Bibliothek <a class="header-anchor" href="#atlas-icon-bibliothek" aria-label="Permalink to &quot;ATLAS Icon Bibliothek&quot;">​</a></h1><p>Die ATLAS Icon Bibliothek ist ein eigenständiges Plugin zum Suchen und Durchsuchen von Iconsets. Die Icons erscheinen in einem Raster mit bis zu 20 Spalten; bei großen Sets lädt die Oberfläche nur den sichtbaren Ausschnitt. Ein Klick kopiert den vollständigen Namen wie <code>mdi:home</code> oder <code>atlas:home</code>.</p><p>Der MDI-Katalog ist im Plugin enthalten und wird in der Quellenanzeige als integrierte Quelle ausgewiesen. Er erscheint nicht als Home-Assistant-Dateipfad. SVG-Icons verwenden standardmäßig die Akzentfarbe; das Erscheinungsbild folgt dem Hell-/Dunkel-Farbschema des Browsers.</p><h2 id="iconsets-laden" tabindex="-1">Iconsets laden <a class="header-anchor" href="#iconsets-laden" aria-label="Permalink to &quot;Iconsets laden&quot;">​</a></h2><p>Seit 0.1.9 werden Größenänderungen des Rasters zusammengefasst, um eine beobachtete ResizeObserver-Rückkopplung in WebKit zu vermeiden. Die teilweise fehlende Darstellung in einer Safari-16.6-Ventura-VM ist noch nicht als behoben bestätigt. Gespeicherte Iconsets bleiben erhalten.</p><p>Das Plugin-Paket enthält den MDI-Katalog. Icon-Studio-Sammlungen und unterstützte statische Home-Assistant-Iconsets können als JavaScript-Datei vom PC importiert oder über File Studio aus <code>/config/www/</code> geladen werden. Der Scanner durchsucht auch Unterordner, darunter <code>/config/www/community/</code> (in Home Assistant als <code>/local/community/</code> erreichbar). Er berücksichtigt unterstützte JavaScript-Iconsets, wenn „icon“ im Datei- oder Ordnernamen vorkommt, und fasst Dateien mit gleichem Präfix zusammen. Beispielsweise werden Hue, Selfh.st, BHA, Yandex, Custom Icons, KNX, Thermal Comfort und Custom Brand Icons unterstützt. Die JavaScript-Dateien werden als Daten gelesen, nicht ausgeführt. Importierte Sammlungen werden lokal im Browser gespeichert.</p><p>Einige ältere Home-Assistant-Iconsets stellen über <code>window.customIcons</code> eine Icon-Namensliste bereit und können damit angezeigt werden. Die neuere <code>window.customIconsets</code>-Schnittstelle bietet keinen allgemeinen Mechanismus, um alle Icon-Namen eines beliebigen Sets aufzulisten. Solche Sets lassen sich nur anzeigen, wenn sie zusätzlich eine lesbare Namensliste bereitstellen.</p><p>Für den Zugriff auf <code>/config/www/</code> muss dieser Pfad in File Studio freigegeben sein. Das Plugin benötigt dafür keinen Home-Assistant-Token.</p><h2 id="installation-und-quellcode" tabindex="-1">Installation und Quellcode <a class="header-anchor" href="#installation-und-quellcode" aria-label="Permalink to &quot;Installation und Quellcode&quot;">​</a></h2><p>Im ATLAS Plugin-Manager das externe Repository hinzufügen:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/rockbaer2007/atlas-icon-library-plugin/main/repository.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Voraussetzung ist ATLAS 0.1.248 oder neuer, da diese Version die externe Paketinstallation korrigiert.</p><p>Der Quellcode und die Entwicklungshinweise stehen im <a href="https://github.com/rockbaer2007/atlas-icon-library-plugin" target="_blank" rel="noreferrer">GitHub-Repository</a>.</p>',13)])])}const p=n(a,[["render",r]]);export{m as __pageData,p as default};
